"""Exact composed preimage excerpts for V50 offline tests.

Extracted from the V49 c442a27f native CI final TI source patch applied to
pinned TI 3615ad5d, reversed to the V48 stack and B1 ZMac preimages. They
are anchors only: the full composite runs on GitHub-hosted native CI.
"""
STACK = '/* Exact composed V48 dispatcher (TI 3615ad5d + B1 + V6 + V48). */\nuint32_t **pTasksEvents;\nextern void B4_V6_StackPulse(uint32_t,uint32_t);\nstatic void stackTaskFxn(UArg a0, UArg a1);\n\nstatic void stackServiceFxnsInit( void )\n{\n    tmpServiceId = OsalPort_registerTask(stackTaskHndl, stackSemHandle, &nwkServiceEvents);\n    nwk_init( tmpServiceId );\n    pTasksEvents[idx] = &nwkServiceEvents;\n}\n\nstatic void stackTaskFxn(UArg a0, UArg a1)\n{\n    /* Task context: pZStackCfg is bound; NV mutex is initialized.\n     * Reject incoherent restored state before MAC/stack init. */\n    if (!b1_sec_validate_restored()) return;\n    //  initialize the MAC\n\n    stackInit();\n\n    OsalPortTimers_registerCleanupEvent(stackServiceId, OSALPORT_CLEAN_UP_TIMERS_EVT);\n\n// race condition: Stack task must register with OsalPort before NPI task,\n// but NPI task must register with OsalPort *before* stack task is able to\n// start running. This Mutex is unlocked by the NPI task after it has\n// finished initializing.\n#ifdef NPI\n    Semaphore_pend(npiInitializationMutexHandle, BIOS_WAIT_FOREVER);\n#endif\n\n    while(1)\n    {\n      /* Block here until TIRTOS task gets an event */\n      Semaphore_pend(stackSemHandle, BIOS_WAIT_FOREVER);\n\n      uint8_t idx = 0;\n\n      /* B4_V48_RETAINED_ZDAPP_DISPATCH_FAIRNESS\n       * When B1 already POSTED retained INIT/START, do not let endlessly\n       * ready, lower-index services starve its existing ZDApp dispatcher.\n       * This is selection, not dispatch: the original CS/clear/call/merge\n       * and semaphore credit logic below remain strictly unchanged.\n       */\n      if (b1_retained_attempt_active() &&\n          (zdAppServiceEvents & (ZDO_NETWORK_INIT | ZDO_NETWORK_START)))\n      {\n        for (idx=0; idx<zstackTasksCnt; ++idx)\n          if (pTasksEvents[idx] == &zdAppServiceEvents) break;\n      }\n      else\n      {\n        // Original priority-based first-ready selection for all other work.\n        do {\n          if (*(pTasksEvents[idx]))\n          {\n            break;\n          }\n        } while (++idx < zstackTasksCnt);\n      }\n\n      if (idx < zstackTasksCnt)\n      {\n        uint32_t events, key;\n\n        key = OsalPort_enterCS();\n        events = *(pTasksEvents[idx]);\n        *(pTasksEvents[idx]) = 0;  // Clear the Events for this task.\n        OsalPort_leaveCS(key);\n\n        b1_evidence_dispatch(idx, events);\n        B4_V6_StackPulse((uint32_t)idx+1u,0u);\n        events = (zstackTasksArr[idx])( 0U, events );\n        B4_V6_StackPulse((uint32_t)idx+1u,1u);\n        b1_evidence_dispatch_end(events);\n\n        key = OsalPort_enterCS();\n        *(pTasksEvents[idx]) |= events;  // Add back unprocessed events to the current task.\n        OsalPort_leaveCS(key);\n        if (events != 0u) Semaphore_post(stackSemHandle);\n      }\n    }\n}\n'
ZMAC = '#include "mac_api.h"\nextern int b1_nv_runtime_hold_active(void);\n\nuint8_t ZMacDataReqSec( ZMacDataReq_t *pData, applySecCB_t secCB )\n{\n  if (b1_nv_runtime_hold_active()) return MAC_NO_RESOURCES;\n  ApiMac_mcpsDataReq_t dataReq;\n  uint8_t stat = MAC_NO_RESOURCES;\n\n  memset(&dataReq, 0, sizeof(ApiMac_mcpsDataReq_t));\n\n  OsalPort_memcpy( &dataReq.dstAddr, &pData->DstAddr, sizeof(ApiMac_sAddr_t) );\n  dataReq.dstPanId = pData->DstPANId;\n  dataReq.srcAddrMode = (ApiMac_addrType_t)pData->SrcAddrMode;\n\n  dataReq.msduHandle = pData->Handle;\n\n  convertToTxOptions(&dataReq.txOptions, pData->TxOptions);\n\n  dataReq.channel = pData->Channel;\n  dataReq.power = pData->Power;\n\n  dataReq.gpOffset = pData->GpOffset;\n  dataReq.gpDuration = pData->GpDuration;\n\n  dataReq.msdu.len = pData->msduLength;\n  dataReq.msdu.p = OsalPort_malloc(dataReq.msdu.len);\n\n  if (dataReq.msdu.p)\n  {\n      /* Copy data */\n      OsalPort_memcpy( dataReq.msdu.p, pData->msdu, pData->msduLength );\n\n      /* Encrypt in place */\n      if ( secCB )\n      {\n        if ( secCB( dataReq.msdu.len, dataReq.msdu.p ) != ZSuccess )\n        {\n          /* Deallocate the buffer */\n          OsalPort_free( dataReq.msdu.p );\n\n          return ( MAC_NO_RESOURCES );\n        }\n      }\n  }\n\n  /* Call Mac Data Request */\n  stat = MAP_MAC_McpsDataReq( &dataReq );\n\n  if (dataReq.msdu.p)\n  {\n    OsalPort_free( dataReq.msdu.p );\n  }\n\n  return ( stat );\n}\n'
ZMAC_CB = 'void MAC_CbackEvent(macCbackEvent_t *pData)\n{\n  uint8_t event = pData->hdr.event;\n  (void)event;\n}\n'
